"use client";

import type { ReactNode } from "react";
import { useRef } from "react";
import {
  motion,
  useMotionValue,
  useReducedMotion,
  useSpring,
  useTransform,
  type MotionValue,
} from "motion/react";

export interface DockItem {
  id: string;
  label: string;
  icon: ReactNode;
  onClick?: () => void;
}

export interface DockProps {
  items: DockItem[];
  baseSize?: number;
  maxSize?: number;
  influence?: number;
  className?: string;
}

const SPRING = { mass: 0.1, stiffness: 170, damping: 14 } as const;

export function Dock({
  items,
  baseSize = 44,
  maxSize = 80,
  influence = 140,
  className = "",
}: DockProps) {
  const mouseX = useMotionValue(Infinity);

  return (
    <div
      className={`mx-auto flex h-20 items-end gap-3 rounded-2xl border border-white/10 bg-zinc-900/70 px-3 pb-3 shadow-2xl shadow-black/40 backdrop-blur-md ${className}`}
      role="toolbar"
      aria-label="Dock"
      onMouseMove={(event) => mouseX.set(event.clientX)}
      onMouseLeave={() => mouseX.set(Infinity)}
    >
      {items.map((item) => (
        <DockButton
          key={item.id}
          item={item}
          mouseX={mouseX}
          baseSize={baseSize}
          maxSize={maxSize}
          influence={influence}
        />
      ))}
    </div>
  );
}

function DockButton({
  item,
  mouseX,
  baseSize,
  maxSize,
  influence,
}: {
  item: DockItem;
  mouseX: MotionValue<number>;
  baseSize: number;
  maxSize: number;
  influence: number;
}) {
  const ref = useRef<HTMLButtonElement>(null);
  const reduceMotion = useReducedMotion();
  const hovered = useMotionValue(0);
  const restingSize = useMotionValue(baseSize);

  const distance = useTransform(mouseX, (x) => {
    const bounds = ref.current?.getBoundingClientRect();

    if (!bounds) {
      return influence + 1;
    }

    return x - (bounds.x + bounds.width / 2);
  });

  const targetSize = useTransform(
    distance,
    [-influence, 0, influence],
    [baseSize, maxSize, baseSize],
    { clamp: true },
  );

  const size = useSpring(reduceMotion ? restingSize : targetSize, SPRING);

  return (
    <motion.button
      ref={ref}
      type="button"
      style={{ width: size, height: size }}
      onClick={item.onClick}
      onHoverStart={() => hovered.set(1)}
      onHoverEnd={() => hovered.set(0)}
      onFocus={() => hovered.set(1)}
      onBlur={() => hovered.set(0)}
      whileTap={{ scale: 0.88 }}
      className="group relative grid place-items-center rounded-xl bg-zinc-800 text-zinc-200 outline-none ring-cyan-400/70 transition-colors hover:bg-zinc-700 focus-visible:ring-2"
      aria-label={item.label}
    >
      <span className="pointer-events-none flex size-[55%] items-center justify-center">
        {item.icon}
      </span>

      <Tooltip hovered={hovered} label={item.label} />
    </motion.button>
  );
}

function Tooltip({
  hovered,
  label,
}: {
  hovered: MotionValue<number>;
  label: string;
}) {
  const opacity = useTransform(hovered, [0, 1], [0, 1]);
  const y = useTransform(hovered, [0, 1], [4, 0]);

  return (
    <motion.span
      style={{ opacity, y }}
      className="pointer-events-none absolute -top-9 whitespace-nowrap rounded-md bg-zinc-100 px-2 py-1 text-xs font-medium text-zinc-900 shadow-lg"
      aria-hidden
    >
      {label}
    </motion.span>
  );
}
